struct Memo<K, V> { map: std::sync::Mutex<std::collections::HashMap<K, V>> }

impl<K: Eq + std::hash::Hash + Clone, V: Clone> Memo<K, V> {
    fn get_or_insert_with(&self, key: K, load: impl FnOnce() -> V) -> V {
        if let Some(v) = self.map.lock().unwrap().get(&key).cloned() {
            return v;                                  // guard drops before loader
        }
        let v = load();                                // no lock held; duplicate loads need single-flight
        let mut m = self.map.lock().unwrap();
        if let Some(existing) = m.get(&key).cloned() {
            return existing;
        }
        m.insert(key, v.clone());                       // capacity/eviction policy is still yours
        v
    }
}
// single computed value: std::sync::OnceLock<T> (no eviction, no TTL)

