use moka::sync::Cache;
use std::time::Duration;
use std::sync::Arc;

let cache: Cache<u64, Arc<Product>> = Cache::builder()
    .max_capacity(10_000)
    .time_to_live(Duration::from_secs(600))
    .build();

let p = cache.get(&id).unwrap_or_else(|| {
    let v = Arc::new(load(id));
    cache.insert(id, v.clone());
    v
});
